package kr.workbench;
import burp.api.montoya.MontoyaApi;import javax.swing.*;import java.awt.*;import java.util.*;
/** Each requested target owns its own panel, jobs, selection, packets and stop state. */
public final class PassiveScanWorkspace extends JPanel implements AutoCloseable {
 final MontoyaApi api;final JTabbedPane targets=new JTabbedPane();final JTextField input=new JTextField(32);final LinkedHashMap<String,PassiveScanPanel> panels=new LinkedHashMap<>();final JLabel note=new JLabel("트래픽 URL 우클릭 → URL 수집 · 최대 8개 대상");private final TargetWindow targetSettings;private final JLabel targetSummary;boolean horizontal;java.util.function.BiConsumer<String,String> discovery=(url,source)->{};
 public PassiveScanWorkspace(MontoyaApi api){super(new BorderLayout(6,6));this.api=api;targetSummary=new JLabel("대상 · SCOPE에서 선택하세요");targetSettings=new TargetWindow(this,"URL 수집 · 대상 설정",()->{JButton prepare=new JButton("대상 열기");prepare.setName("wb.target.prepare");prepare.addActionListener(e->{try{open(input.getText(),false);closeTargetWindow();}catch(Exception ex){note.setText(ex.getMessage());}});return TargetWindow.options(TargetWindow.scopes(api,input::setText),WorkbenchUi.row(new JLabel("URL / 도메인"),input),WorkbenchUi.row(prepare,new JLabel("대상을 준비한 뒤 수집 버튼으로 시작합니다.")));});setBorder(BorderFactory.createEmptyBorder(6,6,6,6));targets.setTabLayoutPolicy(JTabbedPane.SCROLL_TAB_LAYOUT);JButton start=new JButton("대상 수집 시작"),close=new JButton("선택 대상 닫기");start.addActionListener(e->{int index=targets.getSelectedIndex();if(index<0)targetSettings.open();else ((PassiveScanPanel)targets.getComponentAt(index)).collect();});close.addActionListener(e->{int index=targets.getSelectedIndex();if(index<0)return;PassiveScanPanel panel=(PassiveScanPanel)targets.getComponentAt(index);panel.close();panels.values().remove(panel);targets.remove(index);});JPanel toolbar=new JPanel(new BorderLayout());toolbar.add(WorkbenchUi.row(targetSummary,targetSettings.button(),start,close));toolbar.add(note,BorderLayout.SOUTH);add(toolbar,BorderLayout.NORTH);add(targets);targets.addChangeListener(e->{Component selected=targets.getSelectedComponent();String key=panels.entrySet().stream().filter(entry->entry.getValue()==selected).map(java.util.Map.Entry::getKey).findFirst().orElse("");input.setText(key);TargetWindow.show(targetSummary,key,"대상 · SCOPE에서 선택하세요");});WorkbenchUi.style(this);}
 PassiveScanPanel open(String url,boolean execute){String host=PassiveUrls.domain(url);String key=url.strip().contains("://")?java.net.URI.create(url.strip()).normalize().toString().split("#",2)[0]:host;PassiveScanPanel panel=panels.get(key);if(panel==null){if(panels.size()>=8)throw new IllegalArgumentException("대상 탭은 최대 8개입니다. 사용하지 않는 탭을 닫아주세요.");panel=new PassiveScanPanel(api);panel.discovery=(found,source)->discovery.accept(found,source);panel.target.setText(host);panel.target.setEditable(false);panels.put(key,panel);targets.addTab(host+(key.contains("://")?" · "+java.net.URI.create(key).getPath():""),panel);targets.setToolTipTextAt(targets.getTabCount()-1,key);WorkbenchUi.packetLayout(panel,horizontal);}targets.setSelectedComponent(panel);input.setText(url);TargetWindow.show(targetSummary,key,"대상 · SCOPE에서 선택하세요");note.setText("선택 대상: "+key+" · 과거 URL은 도메인 기준으로 수집합니다.");if(execute)panel.collect();return panel;}
 private void closeTargetWindow(){targetSettings.closeWindow();}
 void layout(boolean horizontal){this.horizontal=horizontal;for(PassiveScanPanel p:panels.values())WorkbenchUi.packetLayout(p,horizontal);}
 @Override public void close(){targetSettings.close();for(PassiveScanPanel p:panels.values())p.close();panels.clear();targets.removeAll();}
}
